// Illustrative only — loops on boards with snakes.
int minRolls(int square, int[] jump, boolean[] inPath) {
    if (square == 100) return 0;
    inPath[square] = true;
    int best = Integer.MAX_VALUE;
    for (int roll = 1; roll <= 6; roll++) {
        int next = square + roll;
        if (next > 100) break;
        next = jump[next];                 // apply ladder/snake on landing
        if (!inPath[next]) {               // crude cycle guard
            int sub = minRolls(next, jump, inPath);
            if (sub != Integer.MAX_VALUE) best = Math.min(best, 1 + sub);
        }
    }
    inPath[square] = false;
    return best;                            // explores all paths → exponential
}

