public int quickestWayUp(int[][] ladders, int[][] snakes) {
    int[] jump = new int[101];
    for (int i = 1; i <= 100; i++) jump[i] = i;
    for (int[] l : ladders) jump[l[0]] = l[1];
    for (int[] s : snakes) jump[s[0]] = s[1];

    int[] dist = new int[101];
    Arrays.fill(dist, -1);
    dist[1] = 0;
    Deque<Integer> queue = new ArrayDeque<>();
    queue.offer(1);
    while (!queue.isEmpty()) {              // iterative BFS, cycle-safe
        int u = queue.poll();
        if (u == 100) return dist[u];
        for (int roll = 1; roll <= 6; roll++) {
            int next = u + roll;
            if (next > 100) break;
            next = jump[next];              // apply ladder/snake on landing
            if (dist[next] == -1) {
                dist[next] = dist[u] + 1;
                queue.offer(next);
            }
        }
    }
    return dist[100];                        // -1 if never reached
}

code.python:
from collections import deque

def quickest_way_up(self, ladders: list[list[int]], snakes: list[list[int]]) -> int:
    jump = list(range(101))                 # jump[i] = i by default
    for start, end in ladders:
        jump[start] = end
    for start, end in snakes:
        jump[start] = end

    dist = [-1] * 101
    dist[1] = 0
    queue = deque([1])
    while queue:                            # iterative BFS, cycle-safe
        u = queue.popleft()
        if u == 100:
            return dist[u]
        for roll in range(1, 7):
            nxt = u + roll
            if nxt > 100:
                break
            nxt = jump[nxt]                  # apply ladder/snake on landing
            if dist[nxt] == -1:
                dist[nxt] = dist[u] + 1
                queue.append(nxt)
    return dist[100]                         # -1 if never reached

